#include <bits/stdc++.h>
using namespace std;
#define MODULUS 1000000007
typedef unsigned long long ull_typed;

struct MatStruct {
    ull_typed mat[35][35];
    int dim;
    friend MatStruct operator*(const MatStruct &A, const MatStruct &B) {
        MatStruct C;
        C.dim = A.dim;
        for (int i = 0; i < A.dim; ++i) {
            for (int j = 0; j < A.dim; ++j) {
                C.mat[i][j] = 0;
                for (int k = 0; k < A.dim; ++k) {
                    C.mat[i][j] += A.mat[i][k] * B.mat[k][j];
                }
                C.mat[i][j] %= MODULUS;
            }
        }
        return C;
    }
};

int main() {
    ull_t n_value, m_value;
    cin >> n_value >> m_value;
    MatStruct base, identity;
    base.dim = m_value + 1;
    for (int i = 0; i <= m_value; ++i) {
        base.mat[i][i] = 1;
        base.mat[0][i] = 1;
    }
    identity.dim = m_value + 1;
    for (int i = 0; i <= m_value; ++i) {
        identity.mat[i][i] = 1;
    }

    ull_t y_counter = 1, y_powered = 1, level_idx = 0, total_sum = 0;
    while (y_powered * m_value <= n_value) {
        y_powered *= m_value;
        ++level_idx;
    }

    vector<vector<MatStruct>> bi_array(level_idx + 1, vector<MatStruct>(m_value + 1));
    for (int t = 0; t <= level_idx; ++t) {
        if (t > 0) {
            bi_array[t][0] = bi_array[t - 1][0];
            for (int i = 1; i <= m_value; ++i) {
                bi_array[t][0] = bi_array[t][0] * bi_array[t - 1][i];
            }
        }
        for (int i = 1; i <= m_value; ++i) {
            bi_array[t][i] = bi_array[t][i - 1];
            for (int j = m_value - 2; j >= 0; --j) {
                for (int k = 0; k <= m_value; ++k) {
                    swap(bi_array[t][i].mat[j][k], bi_array[t][i].mat[j + 1][k]);
                }
            }
            for (int j = m_value - 2; j >= 0; --j) {
                for (int k = 0; k <= m_value; ++k) {
                    swap(bi_array[t][i].mat[k][j], bi_array[t][i].mat[k][j + 1]);
                }
            }
        }
    }

    MatStruct currentMat = identity;
    while (total_sum < n_value) {
        if (total_sum + y_powered <= n_value) {
            total_sum += y_powered;
            currentMat = currentMat * bi_array[level_idx][0];
            y_counter = (y_counter + 1) % m_value;
        } else {
            y_powered /= m_value;
            --level_idx;
        }
    }

    ull_t final_answer = 0;
    for (int i = 0; i <= m_value; ++i) {
        final_answer = (final_answer + currentMat.mat[i][m_value]) % MODULUS;
    }
    cout << final_answer << "\n";
}
